    "joinrows.py": "def left_join(left_rows, right_index):
    """Perform a stable left equijoin.

    Args:
        left_rows (list): List of dicts with keys "key" and "value" representing the left side.
        right_index (dict): Mapping from key to list of right-side values (as produced by ``index_rows``).

    Returns:
        list: List of result rows ``{"key": key, "left": left_value, "right": right_value}``.
              If a left row has no matching right rows, a single row with ``right`` set to ``None`` is emitted.
    """
    result = []
    for left in left_rows:
        key = left.get("key")
        left_val = left["value"]
        # Null keys never match any right rows, even other nulls.
        if key is None:
            result.append({"key": None, "left": left_val, "right": None})
            continue
        matches = right_index.get(key, [])
        if matches:
            for right_val in matches:
                result.append({"key": key, "left": left_val, "right": right_val})
        else:
            result.append({"key": key, "left": left_val, "right": None})
    return result
